content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Team",
      "desc": "Group of people estimating work together.",
      "attributes": [
        "Moderator",
        "Team Member"
      ]
    },
    {
      "name": "Moderator",
      "desc": "Person who leads estimation sessions and records results."
    },
    {
      "name": "Team Member",
      "desc": "Person who joins estimation sessions and gives estimates."
    },
    {
      "name": "Estimation Session",
      "desc": "Meeting where the team estimates work items.",
      "attributes": [
        "Timer",
        "Round",
        "Estimation Backlog",
        "Session Log Data"
      ]
    },
    {
      "name": "Timer",
      "desc": "Tracks time during estimation rounds."
    },
    {
      "name": "Round",
      "desc": "One estimation cycle for an item."
    },
    {
      "name": "Estimation Backlog",
      "desc": "List of items to be estimated."
    },
    {
      "name": "Session Log Data",
      "desc": "Collected data of all votes, estimates, and results."
    },
    {
      "name": "Item",
      "desc": "Work unit selected for estimation.",
      "attributes": [
        "Estimation History"
      ]
    },
    {
      "name": "Estimation History",
      "desc": "Record of past votes and discussions for an item."
    },
    {
      "name": "Estimate Vote",
      "desc": "Individual estimate from a team member.",
      "attributes": [
        "Estimation Scale"
      ]
    },
    {
      "name": "Estimation Scale",
      "desc": "the scale or metric on which the Item will be rated"
    },
    {
      "name": "Task List",
      "desc": "External source of items added to the backlog."
    },
    {
      "name": "Voting Reveal",
      "desc": "Moment when all votes are shown to the team."
    },
    {
      "name": "Agreed Estimate",
      "desc": "Final shared estimate after discussion."
    },
    {
      "name": "Stakeholder",
      "desc": "Person interested in estimation outcomes."
    }
  ]
}
```

